SELECT count(*) AS row_count, min(a) AS min_a, max(a) AS max_a, sum(a) AS sum_a, count(DISTINCT a) AS distinct_a, sum(CASE WHEN b='xxx' THEN 1 ELSE 0 END) AS xxx_rows, (SELECT count(*) FROM sqlite_schema WHERE type='table' AND name='t1') AS table_exists, (SELECT count(*) FROM sqlite_schema WHERE type='index' AND name='i1' AND tbl_name='t1') AS index_exists, (SELECT stat FROM sqlite_stat1 WHERE tbl='t1' AND idx='i1') AS index_stat FROM t1;